// Client is the root Windows CSP SDK client. It fans a single transport
// out to every generated CSP service, grouped into families.
//
// Generated from the February 2026 DDF v2 release.
type Client struct {
	transport client.Client
	// CSP groups the standalone configuration service providers.
	CSP *CSPServices
	// Policy groups the Policy CSP areas (./Vendor/MSFT/Policy/Config).
	Policy *PolicyServices
}

// NewClient wires every generated CSP service to transport.
func NewClient(transport client.Client) *Client {
	return &Client{
		transport: transport,
		CSP:       newCSPServices(transport),
		Policy:    newPolicyServices(transport),
	}
}

// Transport returns the transport the client was built with.
func (c *Client) Transport() client.Client { return c.transport }

